mod common;
use common::*;
use sodeck_updater::{store::*,model::*,plan::Target};

#[test]fn operation_ids_do_not_repeat_or_change_side_effects(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();let id=uuid::Uuid::new_v4().to_string();let request=serde_json::json!({"components":["core"]});assert!(s.begin(&id,"shell","download",&request).unwrap().1);assert!(!s.begin(&id,"shell","download",&request).unwrap().1);assert!(s.begin(&id,"plugin","download",&request).is_err());assert!(s.begin(&id,"shell","install",&request).is_err());drop(s);let s=Store::open(dir.path()).unwrap();assert!(!s.operation(&id).unwrap().running);assert_eq!(s.operation(&id).unwrap().stage,Stage::Failed);}
#[test]fn local_same_byte_import_stays_local_after_restart(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();let d="a".repeat(64);s.source_intent("sodeck.terminal",None,&d,Origin::Bundled,"seed").unwrap();s.source_complete("sodeck.terminal",Some(&d)).unwrap();assert!(s.source_for("sodeck.terminal",&d).1);s.source_intent("sodeck.terminal",Some(&d),&d,Origin::Local,"manual").unwrap();drop(s);let mut s=Store::open(dir.path()).unwrap();assert!(!s.source_for("sodeck.terminal",&d).1);s.source_complete("sodeck.terminal",Some(&d)).unwrap();assert_eq!(s.source_for("sodeck.terminal",&d),(Origin::Local,false));s.follow_official("sodeck.terminal",&d,None).unwrap();assert_eq!(s.source_for("sodeck.terminal",&d),(Origin::Local,true));}
#[test]fn source_storage_failure_does_not_change_in_memory_origin(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();std::fs::create_dir(dir.path().join("sources.json")).unwrap();assert!(s.source_intent("sodeck.terminal",None,&"a".repeat(64),Origin::Official,"update").is_err());assert!(s.sources.plugins.is_empty());}
#[test]fn same_sequence_catalog_cannot_be_replaced(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();let(mut c,_)=fixture();s.accept_catalog(&verified(&c)).unwrap();c.source_commit="b".repeat(40);assert!(s.accept_catalog(&verified(&c)).is_err());let(_,_,keys)=signed(&c);assert!(s.catalog(&keys,Channel::Stable).unwrap().is_some());}
#[test]fn corrupted_state_preserves_evidence_and_disables_automatic_check(){let dir=tempfile::tempdir().unwrap();std::fs::write(dir.path().join("state.json"),"broken-state").unwrap();let s=Store::open(dir.path()).unwrap();assert!(!s.policy.auto_check);assert!(!s.warnings.is_empty());assert!(s.state.installs.is_empty());assert_eq!(std::fs::read(dir.path().join("state.json")).unwrap(),b"broken-state");assert_eq!(std::fs::read_dir(dir.path().join("diagnostics")).unwrap().count(),1);}
#[test]fn prepared_cache_cannot_be_evicted_for_another_download(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();let(c,_)=fixture();let release=c.plugins["sodeck.terminal"].current.clone();let d=release.asset.archive_sha256.clone();let path=dir.path().join("cache").join(&d);std::fs::File::create(&path).unwrap().set_len(MAX_CACHE-4096).unwrap();let mut next=s.state.clone();next.installs.insert("sodeck.terminal".into(),InstallIntent{operation_id:"test".into(),target:Target::Plugin{plugin_id:"sodeck.terminal".into(),release,requires_core:None},catalog_digest:"a".repeat(64),stage:Stage::Ready,activation_attempt:None,previous_digest:None,required_core:None});s.save_state(next).unwrap();assert!(s.reserve_space(1024*1024,&Default::default()).is_err());assert!(path.is_file());}
#[test]fn policy_save_is_revisioned_and_idempotent(){let dir=tempfile::tempdir().unwrap();let mut s=Store::open(dir.path()).unwrap();let g=s.policy.generation.clone();let id=uuid::Uuid::new_v4().to_string();s.policy_commit(&g,"0",false,&id).unwrap();assert!(!s.policy_commit(&g,"0",false,&id).unwrap().auto_check);assert!(s.policy_commit(&g,"0",true,&uuid::Uuid::new_v4().to_string()).is_err());}
#[test]fn newer_state_with_unknown_fields_is_never_reset(){
    let dir=tempfile::tempdir().unwrap();let bytes=br#"{"schemaVersion":2,"newMeaning":true}"#;
    std::fs::write(dir.path().join("state.json"),bytes).unwrap();
    assert!(matches!(Store::open(dir.path()),Err(e) if e.code=="UPDATE_STATE_UNSUPPORTED"));
    assert_eq!(std::fs::read(dir.path().join("state.json")).unwrap(),bytes);
}
#[test]fn reopened_core_updates_the_original_receipt_only_for_exact_identity(){
    for correct in [false,true]{
        let dir=tempfile::tempdir().unwrap();let mut store=Store::open(dir.path()).unwrap();let (_,mut snapshot)=fixture();let id=uuid::Uuid::new_v4().to_string();store.begin(&id,"shell","updates.install",&serde_json::json!({})).unwrap();
        let mut next=store.state.clone();next.handoff=Some(CoreHandoff{operation_id:id.clone(),target_version:"2.0.1".into(),build_id:"a".repeat(64),channel:Channel::Stable,asset_digest:"c".repeat(64),stage:Stage::HandoffAttempted});store.save_state(next).unwrap();drop(store);
        let mut store=Store::open(dir.path()).unwrap();snapshot.runtime.app_version="2.0.1".into();if correct{snapshot.runtime.build_id="a".repeat(64);}
        store.reconcile_handoff(&snapshot.runtime).unwrap();let op=store.operation(&id).unwrap();assert!(!op.running);assert_eq!(op.stage,if correct{Stage::Installed}else{Stage::Failed});assert_eq!(op.error.is_none(),correct);
    }
}
